import React from "react";

export default function Header({ profile, socialLinks }) {
  return (
    <header className="mb-16">
      <h1 className="text-4xl font-normal tracking-tight sm:text-5xl">
        {profile.name}
      </h1>

      <div className="mt-6 max-w-3xl text-base leading-7 text-neutral-700 sm:text-lg">
        {profile.description}
      </div>

      <div className="mt-6 flex flex-wrap items-center gap-x-3 gap-y-2 text-sm text-neutral-700 sm:text-base">
        {socialLinks.map((link, index) => (
          <React.Fragment key={link.label}>
            <a
              href={link.href}
              target="_blank"
              rel="noopener noreferrer"
              className="hover:text-black underline underline-offset-2"
            >
              {link.label}
            </a>
            {index < socialLinks.length - 1 && (
              <span className="text-neutral-400">/</span>
            )}
          </React.Fragment>
        ))}
      </div>
    </header>
  );
}
